self.KB_CONTENT["card:751178"]={"id":"card:751178","ty":"card","sourceId":"751178","title":"『傳票總號重排作業』中的『選擇傳票單別 (ACT.TA001)』為何？","ver":"iGP","topic":"單別","keywords":["單別","傳票"],"y":"other","answer":"* 可複選(icon)或[F2]單別資料查詢，只能查詢單據性質為「9字頭」之單別。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
