self.KB_CONTENT["card:751383"]={"id":"card:751383","ty":"card","sourceId":"751383","title":"『科目/部門預算追加憑證』中的『選擇期別 (MY005)』為何？","ver":"iGP","topic":"憑證","keywords":["憑證","科目","預算"],"y":"other","answer":"* 選擇期別(起)預設『01』。* 會計期制分為12期(01-12)及13期(01-13)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
