self.KB_CONTENT["card:792430"]={"id":"card:792430","ty":"card","sourceId":"792430","title":"『費用申請單明細表』中的『選擇排序』為何？","ver":"GP4以上","topic":"明細表","keywords":["明細表","申請單","費用"],"y":"other","answer":"* 區分1.申請日期及2.單據日期兩種排序方法。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
